import hashlib,json,subprocess,sys,tempfile
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1];SCORER=ROOT/'scripts'/'ember_restart_eval_audiobench_bound.py';PREFLIGHT=ROOT/'scripts'/'ember_restart_eval_execution_preflight.py'
def write_bound_custody(run, destination):
 custody=json.loads((ROOT/'manifests'/'ember-restart-audiobench-custody-v1.json').read_text(encoding='utf-8'))
 custody['closed_run_artifact_sha256']=hashlib.sha256(run.read_bytes()).hexdigest()
 custody['scoring_adapter']['sha256']=hashlib.sha256(SCORER.read_bytes()).hexdigest()
 identity={'benchmark_id':custody['benchmark_id'],'benchmark_version':custody['benchmark_version'],'suite':custody['suite'],'upstream_tree_git_sha1':custody['upstream_tree_git_sha1'],'license_sha256':custody['license_sha256'],'scoring_adapter':custody['scoring_adapter']}
 custody['protocol_sha256']=hashlib.sha256(json.dumps(identity,sort_keys=True,separators=(',',':')).encode('utf-8')).hexdigest()
 destination.write_text(json.dumps(custody,sort_keys=True),encoding='utf-8')
